changeSet.sql:
ALTER TABLE votality_surveys 
ADD CONSTRAINT uq_campaign_pin_location 
UNIQUE (campaign_id, location);

CREATE OR REPLACE FUNCTION fn_prevent_survey_update()
RETURNS TRIGGER AS $$
BEGIN
    RAISE EXCEPTION 'Regla 4.2 Violada: Los registros en votality_surveys son inmutables tras su guardado para garantizar la auditoría electoral.';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_surveys_prevent_update
BEFORE UPDATE ON votality_surveys
FOR EACH ROW
EXECUTE FUNCTION fn_prevent_survey_update();

rollback.sql:
DROP TRIGGER IF EXISTS trg_surveys_prevent_update ON votality_surveys;
DROP FUNCTION IF EXISTS fn_prevent_survey_update();
ALTER TABLE votality_surveys DROP CONSTRAINT IF EXISTS uq_campaign_pin_location;
DROP INDEX IF EXISTS idx_votality_surveys_location_gist;
DROP INDEX IF EXISTS idx_votality_surveys_respondent_name_az;
